/* Import after the host shadcn stylesheet. Activate on <html>, with .dark. */
:root[data-ui-theme="traveler"] {
  color-scheme: dark;
  --background: #111315;
  --foreground: #f2eee5;
  --card: #1b1e21;
  --card-foreground: #f2eee5;
  --popover: #24282d;
  --popover-foreground: #f2eee5;
  --primary: #e4dccb;
  --primary-foreground: #1a1c1f;
  --secondary: #30363d;
  --secondary-foreground: #f2eee5;
  --muted: #24282d;
  --muted-foreground: #b9b3a7;
  --accent: #30363d;
  --accent-foreground: #f2eee5;
  --destructive: #e6a19a;
  --destructive-foreground: #261513;
  --border: #666761;
  --input: #96968d;
  --ring: #c2d7e8;
  --chart-1: var(--primary);
  --chart-2: var(--ring);
  --chart-3: var(--trav-success);
  --chart-4: var(--destructive);
  --chart-5: var(--trav-ornament);
  --radius: 0;
  --radius-xs: 0;
  --font-sans:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-heading: Georgia, "Times New Roman", serif;
  --font-mono: "Lucida Console", "Courier New", monospace;
  --trav-rule: #96968d;
  --trav-ornament: #baa680;
  --trav-success: #b9ceac;
  --trav-success-foreground: #182014;
  --trav-panel-shadow: 4px 6px 0 #090b0d;
  --trav-duration: 140ms;
  --trav-marker-size: 0.5rem;
}

@theme inline {
  --font-heading: var(--font-heading);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-trav-ornament: var(--trav-ornament);
  --color-trav-success: var(--trav-success);
  --color-trav-success-foreground: var(--trav-success-foreground);
  --shadow-trav-panel: var(--trav-panel-shadow);
}

@layer components {
  :where(:root[data-ui-theme="traveler"]) .trav-control {
    outline: 2px solid transparent;
    outline-offset: 3px;
    transition:
      color var(--trav-duration),
      background-color var(--trav-duration),
      border-color var(--trav-duration);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-control:focus-visible {
    outline-color: var(--ring);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-panel {
    background-image: repeating-conic-gradient(
      color-mix(in srgb, var(--foreground) 3%, transparent) 0% 25%,
      transparent 0% 50%
    );
    background-size: 4px 4px;
    /* Offset edges leave a two-pixel step at each corner without clipping content. */
    box-shadow:
      2px 0 0 var(--border),
      -2px 0 0 var(--border),
      0 -2px 0 var(--border),
      0 2px 0 var(--border),
      var(--trav-panel-shadow),
      inset 0 0 0 2px var(--trav-panel-background, var(--card)),
      inset 0 0 0 3px color-mix(in srgb, var(--border) 65%, transparent);
  }

  :where(:root[data-ui-theme="traveler"])
    [data-slot="button"]:where(
      [data-variant="default"],
      [data-variant="secondary"],
      [data-variant="destructive"],
      [data-variant="outline"]
    ) {
    box-shadow:
      inset 0 2px 0 #ffffff18,
      inset 0 -2px 0 #00000040,
      2px 2px 0 #090b0d;
  }

  :where(:root[data-ui-theme="traveler"])
    [data-slot="button"]:where(:enabled, a):active {
    translate: 0 1px;
  }

  :where(:root[data-ui-theme="traveler"]) [data-slot="badge"],
  :where(:root[data-ui-theme="traveler"]) [data-slot="kbd"] {
    font-family: var(--font-mono);
    font-variant-numeric: tabular-nums;
  }

  :where(:root[data-ui-theme="traveler"]) [data-slot="progress"]::after {
    position: absolute;
    inset: 0;
    content: "";
    pointer-events: none;
    background: repeating-linear-gradient(
      to right,
      transparent 0 6px,
      var(--muted) 6px 8px
    );
  }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-ui-theme="traveler"] {
    --trav-duration: 0ms;
  }
}

@media (forced-colors: active) {
  @layer components {
    :where(:root[data-ui-theme="traveler"]) .trav-control:focus-visible {
      outline-color: Highlight;
    }

    :where(:root[data-ui-theme="traveler"]) .trav-panel {
      background-image: none;
      box-shadow: none;
      border-color: CanvasText;
    }

    :where(:root[data-ui-theme="traveler"]) [data-slot="progress"]::after {
      display: none;
    }
  }
}

@layer components {
  :where(:root[data-ui-theme="traveler"]) .trav-menu-surface {
    --trav-panel-background: var(--popover);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item {
    outline: 1px solid transparent;
    outline-offset: -2px;
    transition: background-color var(--trav-duration);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-highlighted] {
    background-color: var(--accent);
    outline: 1px solid var(--ring);
    outline-offset: -2px;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-disabled] {
    pointer-events: none;
    opacity: 0.6;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-pointer::before {
    position: absolute;
    inset-inline-start: 0.65rem;
    width: var(--trav-marker-size);
    height: calc(var(--trav-marker-size) * 1.25);
    content: "";
    background: currentColor;
    clip-path: polygon(
      0 0,
      25% 0,
      25% 20%,
      50% 20%,
      50% 40%,
      75% 40%,
      75% 60%,
      50% 60%,
      50% 80%,
      25% 80%,
      25% 100%,
      0 100%
    );
    visibility: hidden;
    pointer-events: none;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-pointer:dir(rtl)::before {
    transform: scaleX(-1);
  }

  :where(:root[data-ui-theme="traveler"])
    .trav-menu-pointer[data-highlighted]::before {
    visibility: visible;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-overlay[data-state="open"] {
    animation: trav-enter var(--trav-duration) ease-out;
  }

  @keyframes trav-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
}

@media (forced-colors: active) {
  @layer components {
    :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-highlighted] {
      outline-color: Highlight;
    }
  }
}
